const video = document.querySelector('#hero-video');
const toggle = document.querySelector('#video-toggle');
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const constrained = navigator.connection?.saveData || matchMedia('(max-width: 700px)').matches;
video.src = constrained ? 'assets/training-hd.mp4' : 'https://videos.pexels.com/video-files/9944625/9944625-uhd_3840_2160_24fps.mp4';
function updateVideoButton(){toggle.innerHTML = video.paused ? '▶ <span>PLAY FILM</span>' : 'Ⅱ <span>PAUSE FILM</span>';toggle.setAttribute('aria-label',video.paused?'Play background video':'Pause background video');}
if(reduced.matches){video.autoplay=false;video.pause();}else{video.play().catch(updateVideoButton);}
video.addEventListener('play',updateVideoButton);video.addEventListener('pause',updateVideoButton);
video.addEventListener('error',()=>{if(!video.src.endsWith('/assets/training-hd.mp4')){video.src='assets/training-hd.mp4';if(!reduced.matches)video.play().catch(updateVideoButton);}else{toggle.hidden=true;}});
toggle.addEventListener('click',()=>{if(video.paused)video.play().catch(()=>{toggle.textContent='Video unavailable';});else video.pause();});updateVideoButton();
const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.querySelector('nav').classList.toggle('open',open);});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}));
document.querySelectorAll('[data-interest]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#interest').value=a.dataset.interest;}));
document.querySelector('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const data=new FormData(f);const name=String(data.get('name')).trim();if(!name){f.elements.name.setCustomValidity('Please enter your name.');f.elements.name.reportValidity();return;}f.elements.name.setCustomValidity('');const msg=`Hello Sameer Martial Arts Academy!\nMy name is ${name}.\nMobile: ${data.get('phone')}\nI'm interested in: ${data.get('interest')}.${String(data.get('message')).trim()?`\nMy goal/question: ${String(data.get('message')).trim()}`:''}\nPlease share suitable batch timings, fees and availability.`;const link=document.createElement('a');link.href='https://wa.me/918077991383?text='+encodeURIComponent(msg);link.target='_blank';link.rel='noopener';link.click();const status=document.querySelector('#form-status');status.replaceChildren(document.createTextNode('Your message is ready. '));const retry=document.createElement('a');retry.href=link.href;retry.target='_blank';retry.rel='noopener';retry.textContent='Open WhatsApp';retry.style.textDecoration='underline';status.append(retry,document.createTextNode(' and tap send to complete your enquiry.'));});
document.querySelector('input[name="name"]').addEventListener('input',e=>e.target.setCustomValidity(''));
const credits=document.querySelector('#credits');document.querySelector('#credits-open').addEventListener('click',()=>credits.showModal());document.querySelector('#credits-close').addEventListener('click',()=>credits.close());credits.addEventListener('click',e=>{if(e.target===credits){const rect=credits.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)credits.close();}});
document.querySelector('#year').textContent=new Date().getFullYear();
